// The bundled functional engine. QEMU does not implement --describe, so the
// descriptor is built in. The standalone (model=fast) run uses qemu's OWN
// default behavior as far as possible -- the user's post-`--` args (incl. an
// explicit -cpu) still win; only the hybrid fast-leg pins a -cpu. Binary path
// honors $VSIM_QEMU, then $QEMU_BIN_DIR (env or config.env), then the legacy
// in-tree build. Exposed (engine_registry.hpp) so `run --mode fast` resolves
// qemu directly, skipping the per-engine --describe scan whole-registry
// discovery would spawn.
EngineDescriptor builtin_qemu() {
  EngineDescriptor d;
  d.id = kQemuId;
  d.type = "qemu";
  d.kind = "functional";
  d.xlen = 64;
  d.triggers = {"marker", "pc"};
  d.state = {"drain"};
  d.source = "built-in";

  d.roles = {"standalone", "fast-leg"};
  // The hybrid fast-forward leg: load the ELF, drain on the plugin's trigger
  // into {state_out}, exit 200. {plugin}/{mmap}/{mmap_size}/{state_out} are
  // filled by the plan executor (F6); {trigger} is the plugin comma-suffix
  // (empty for marker), folded by leg_trigger_args (F9).
  d.invoke.push_back(
      {"fast-leg",
       {"{bin}", "-object",
        "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
        "-machine", "andes_ae350,memory-backend=mem", "-cpu",
        "andes-ax45mpv,vlen={vlen}", "-nographic", "-semihosting-config",
        "enable=on,target=native", "-bios", "{elf}", "-plugin",
        "{plugin},outfile={state_out}{trigger}"}});

  // The standalone functional run (model=fast). andes_ae350's generic default
  // -cpu hangs C-runtime fixtures, so pin a concrete andes core: the
  // vector-capable andes-ax46mpv. We pass NO vlen -- the cpu model's own QEMU
  // default applies, so both scalar and vector binaries run out of the box; a
  // user who needs a specific width passes it via the post-`--` -cpu (e.g.
  // -cpu andes-ax46mpv,vlen=512), which still wins. run_passthrough fills
  // {bin}/{elf}.
  d.invoke.push_back(
      {"standalone",
       {"{bin}", "-machine", "andes_ae350", "-cpu", "andes-ax46mpv",
        "-nographic", "-semihosting-config", "enable=on,target=native",
        "-bios", "{elf}"}});

  if (const char* q = std::getenv("VSIM_QEMU"); q && *q)
    d.bin_path = q;
  else if (std::string qd = config_env_value("QEMU_BIN_DIR"); !qd.empty())
    d.bin_path = (fs::path(qd) / "qemu-system-riscv64").string();
  else
    d.bin_path =
        (repo_root() / "build" / "qemu" / "qemu-system-riscv64").string();
  return d;
}

